  return imageData[activeCategory.value] || []
})

// 当前视频源
const currentVideoSrc = computed(() => {
  const images = currentImages.value
  if (images.length > 0 && images[activeIndex.value]?.video) {
    return images[activeIndex.value].video
  }
  return ''
})


const getBarWidth = (value) => {
  return (value / maxValue) * 100
}

const handleButtonClick = (category) => {
  activeCategory.value = category
  activeIndex.value = 0
  isExpanded.value = true
  isPlaying.value = false
  expandedCompetition.value = -1
  activePaperIndex.value = -1
  
  // 如果是比赛类别，延迟触发动画
  if (category === '比赛') {
    showCompetitionItems.value = false
    nextTick(() => {
      setTimeout(() => {
        showCompetitionItems.value = true
      }, 300)
    })
  }
  
  // 如果是专利类别，自动播放视频
  if (category === '专利') {
    nextTick(() => {
      setTimeout(() => {
        if (videoPlayer.value && currentVideoSrc.value) {
          videoPlayer.value.play()
            .then(() => {
              isPlaying.value = true
            })
            .catch(err => {
              console.log('自动播放被阻止:', err)
              isPlaying.value = false
            })
        }
      }, 500) // 等待视频容器渲染完成
    })
  }
}

const handleBack = () => {
  isExpanded.value = false
  isPlaying.value = false
  showCompetitionItems.value = false
  expandedCompetition.value = -1
  activePaperIndex.value = -1
  expandedCopyright.value = -1
  activeCategory.value = ''
  // 暂停视频
  if (videoPlayer.value) {
    videoPlayer.value.pause()
  }
}

