}

// 切换播放/暂停
const togglePlay = () => {
  if (!videoPlayer.value) return
  
  if (isPlaying.value) {
    videoPlayer.value.pause()
    isPlaying.value = false
  } else {
    videoPlayer.value.play()
    isPlaying.value = true
  }
}

// 视频播放结束
const handleVideoEnded = () => {
  isPlaying.value = false
}

