// 自动播放视频（当切换图片时）
const autoPlayVideo = async () => {
  if (!showVideo.value || !videoPlayer.value) return
  
  await nextTick()
  
  // 先暂停当前视频
  videoPlayer.value.pause()
  isPlaying.value = false
  
  // 等待视频源更新后自动播放
  setTimeout(() => {
    if (videoPlayer.value && currentVideoSrc.value) {
      videoPlayer.value.play()
        .then(() => {
          isPlaying.value = true
        })
        .catch(err => {
          console.log('自动播放被阻止，需要用户交互:', err)
          isPlaying.value = false
        })
    }
  }, 300)
}

// 获取图片位置样式
const getSlideStyle = (imgIndex) => {
  const totalImages = currentImages.value.length
  
  let diff = imgIndex - activeIndex.value
  
  if (totalImages > 2) {
    if (diff > totalImages / 2) diff -= totalImages
    if (diff < -totalImages / 2) diff += totalImages
  }
  
  let translateX = 0
  let translateZ = 0
  let rotateY = 0
  let scale = 1
  let zIndex = 1
  let opacity = 1
  let blur = 0
  
  if (diff === 0) {
    translateX = 0
    translateZ = 50
    rotateY = 0
    scale = 1
    zIndex = 10
    opacity = 1
    blur = 0
  } else if (diff === 1) {
    translateX = 65
    translateZ = -50
    rotateY = -20
    scale = 0.75
    zIndex = 5
    opacity = 0.5
    blur = 1
  } else if (diff === -1) {
    translateX = -65
    translateZ = -50
    rotateY = 20
    scale = 0.75
    zIndex = 5
    opacity = 0.5
    blur = 1
  } else if (Math.abs(diff) === 2) {
    translateX = diff > 0 ? 100 : -100
    translateZ = -100
    rotateY = diff > 0 ? -30 : 30
    scale = 0.55
    zIndex = 2
    opacity = 0.25
    blur = 2
  } else {
    translateX = diff > 0 ? 130 : -130
    translateZ = -150
    scale = 0.4
    zIndex = 1
    opacity = 0
    blur = 3
  }
  
  if (totalImages === 1) {
    translateX = 0
    translateZ = 0
    scale = 1
    opacity = 1
    zIndex = 10
    blur = 0
    rotateY = 0
  }
  
  if (totalImages === 2) {
    if (diff === 0) {
      translateX = 0
      translateZ = 50
      scale = 1
      opacity = 1
      zIndex = 10
      rotateY = 0
    } else {
      translateX = 55
      translateZ = -50
      scale = 0.75
      opacity = 0.5
      zIndex = 5
      rotateY = -15
    }
  }
  
  return {
    transform: `translateX(${translateX}%) translateZ(${translateZ}px) rotateY(${rotateY}deg) scale(${scale})`,
    zIndex: zIndex,
    opacity: opacity,
    filter: blur > 0 ? `blur(${blur}px)` : 'none',
  }
}

const getSlideClass = (imgIndex) => {
  if (imgIndex === activeIndex.value) return 'slide-active'
  return 'slide-inactive'
}

const setActiveSlide = (imgIndex) => {
  if (activeIndex.value !== imgIndex) {
    activeIndex.value = imgIndex
    autoPlayVideo()
  }
}

const slideNext = () => {
  const total = currentImages.value.length
  if (total > 0) {
    activeIndex.value = (activeIndex.value + 1) % total
    autoPlayVideo()
  }
}

const slidePrev = () => {
  const total = currentImages.value.length
  if (total > 0) {
    activeIndex.value = (activeIndex.value - 1 + total) % total
    autoPlayVideo()
  }
}

const handleWheel = (event) => {
  if (event.deltaY > 0) {
    slideNext()
  } else {
    slidePrev()
  }
}

const dragState = reactive({
  isDragging: false,
  startX: 0,
  currentX: 0,
  threshold: 50
})

const handleDragStart = (event) => {
  dragState.isDragging = true
  dragState.startX = event.clientX
  dragState.currentX = event.clientX
}

const handleDragMove = (event) => {
  if (!dragState.isDragging) return
  dragState.currentX = event.clientX
}

const handleDragEnd = () => {
  if (!dragState.isDragging) return
  
  const deltaX = dragState.currentX - dragState.startX
  
  if (deltaX > dragState.threshold) {
    slidePrev()
  } else if (deltaX < -dragState.threshold) {
    slideNext()
  }
  
  dragState.isDragging = false
}

const handleTouchStart = (event) => {
  const touch = event.touches[0]
  dragState.isDragging = true
  dragState.startX = touch.clientX
  dragState.currentX = touch.clientX
}

const handleTouchMove = (event) => {
  if (!dragState.isDragging) return
  const touch = event.touches[0]
  dragState.currentX = touch.clientX
}

const handleTouchEnd = () => {
  handleDragEnd()
}

const handleImageError = (event) => {
  event.target.src = 'data:image/svg+xml,' + encodeURIComponent(`
    <svg xmlns="http://www.w3.org/2000/svg" width="300" height="200" viewBox="0 0 300 200">
      <rect fill="#1a3a4a" width="300" height="200"/>
      <text x="150" y="90" fill="#1279a4" font-size="14" text-anchor="middle">图片加载失败</text>
      <text x="150" y="120" fill="#666" font-size="32" text-anchor="middle">🖼️</text>
    </svg>
  `)
}

// 监听分类变化，重置视频状态
watch(activeCategory, () => {
  activeIndex.value = 0
  isPlaying.value = false
})

// 监听视频显示状态
watch(showVideo, (newVal) => {
  if (!newVal && videoPlayer.value) {
    videoPlayer.value.pause()
    isPlaying.value = false
  }
})
