/* 使用 calc 让距离也能响应式调整 */
.orbit-pos-0 { top: calc(16% - 0.5vmin); left: 50%; }
.orbit-pos-1 { top: calc(25% - 0.5vmin); left: calc(98% + 0.5vmin); }
.orbit-pos-2 { top: calc(75% + 0.5vmin); left: calc(98% + 0.5vmin); }
.orbit-pos-3 { top: calc(85% + 0.5vmin); left: 50%; }
.orbit-pos-4 { top: calc(75% + 0.5vmin); left: calc(2% - 0.5vmin); }
.orbit-pos-5 { top: calc(25% - 0.5vmin); left: calc(2% - 0.5vmin); }

