/* ============ 比赛内容区域 ============ */
.competition-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding: clamp(20px, 3vh, 40px) clamp(30px, 5vw, 80px);
  overflow-y: auto;
  overflow-x: hidden;
}

.competition-list {
  width: 100%;
  max-width: 800px;
  display: flex;
  flex-direction: column;
  gap: clamp(12px, 2vh, 20px);
}

.competition-item-wrapper {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.competition-item {
  width: 90%;
  display: flex;
  align-items: center;
  gap: clamp(10px, 1.5vw, 20px);
  padding: clamp(12px, 2vh, 20px) clamp(15px, 2.5vw, 30px);
  background: rgba(18, 121, 164, 0.1);
  border: 1px solid rgba(18, 121, 164, 0.3);
  border-radius: clamp(8px, 1vw, 14px);
  cursor: pointer;
  position: relative;
  opacity: 0;
  transform: translateX(-200%) scale(0.5) rotateY(-30deg);
  filter: blur(10px);
  transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.competition-item.from-right {
  transform: translateX(200%) scale(0.5) rotateY(30deg);
}

.competition-item.animate-in {
  opacity: 1;
  transform: translateX(0) scale(1) rotateY(0deg);
  filter: blur(0);
}

.competition-item.from-left.animate-in {
  animation: slideInFromLeft 1.2s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.competition-item.from-right.animate-in {
  animation: slideInFromRight 1.2s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

@keyframes slideInFromLeft {
  0% {
    opacity: 0;
    transform: translateX(-200%) scale(0.5) rotateY(-30deg);
    filter: blur(10px);
    box-shadow: none;
  }
  30% {
    opacity: 0.6;
    filter: blur(5px);
  }
  50% {
    opacity: 1;
    transform: translateX(8%) scale(1.08) rotateY(5deg);
    filter: blur(0);
    box-shadow: 
      0 0 30px rgba(18, 121, 164, 0.6),
      0 0 60px rgba(18, 121, 164, 0.3),
      inset 0 0 20px rgba(18, 121, 164, 0.2);
  }
  70% {
    transform: translateX(-3%) scale(1.03) rotateY(-2deg);
    box-shadow: 
      0 0 20px rgba(18, 121, 164, 0.4),
      0 0 40px rgba(18, 121, 164, 0.2);
  }
  85% {
    transform: translateX(1%) scale(1.01) rotateY(1deg);
  }
  100% {
    opacity: 1;
    transform: translateX(0) scale(1) rotateY(0deg);
    filter: blur(0);
    box-shadow: none;
  }
}

@keyframes slideInFromRight {
  0% {
    opacity: 0;
    transform: translateX(200%) scale(0.5) rotateY(30deg);
    filter: blur(10px);
    box-shadow: none;
  }
  30% {
    opacity: 0.6;
    filter: blur(5px);
  }
  50% {
    opacity: 1;
    transform: translateX(-8%) scale(1.08) rotateY(-5deg);
    filter: blur(0);
    box-shadow: 
      0 0 30px rgba(18, 121, 164, 0.6),
      0 0 60px rgba(18, 121, 164, 0.3),
      inset 0 0 20px rgba(18, 121, 164, 0.2);
  }
  70% {
    transform: translateX(3%) scale(1.03) rotateY(2deg);
    box-shadow: 
      0 0 20px rgba(18, 121, 164, 0.4),
      0 0 40px rgba(18, 121, 164, 0.2);
  }
  85% {
    transform: translateX(-1%) scale(1.01) rotateY(-1deg);
  }
  100% {
    opacity: 1;
    transform: translateX(0) scale(1) rotateY(0deg);
    filter: blur(0);
    box-shadow: none;
  }
}

/* 进场时的光效拖尾 */
.competition-item::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  border-radius: inherit;
  opacity: 0;
  pointer-events: none;
}

/* 边框扫光效果 */
.competition-item::after {
  content: '';
  position: absolute;
  top: -2px;
  left: -2px;
  right: -2px;
  bottom: -2px;
  border-radius: inherit;
  background: linear-gradient(90deg, 
    transparent 0%, 
    transparent 40%, 
    rgba(18, 121, 164, 0.8) 50%, 
    transparent 60%, 
    transparent 100%
  );
  opacity: 0;
  pointer-events: none;
  z-index: -1;
}

.competition-item.animate-in::after {
  animation: borderSweep 1.5s ease-out forwards;
}

@keyframes borderSweep {
  0% {
    opacity: 1;
    background-position: -200% 0;
    background-size: 200% 100%;
  }
  50% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    background-position: 200% 0;
    background-size: 200% 100%;
  }
}

.competition-item.from-left.animate-in::before {
  animation: glowTrailLeft 1.2s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.competition-item.from-right.animate-in::before {
  animation: glowTrailRight 1.2s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

@keyframes glowTrailLeft {
  0% {
    opacity: 0;
    box-shadow: -100px 0 60px 20px rgba(18, 121, 164, 0.8);
  }
  30% {
    opacity: 1;
    box-shadow: -50px 0 40px 15px rgba(18, 121, 164, 0.6);
  }
  60% {
    opacity: 0.5;
    box-shadow: 0 0 20px 5px rgba(18, 121, 164, 0.3);
  }
  100% {
    opacity: 0;
    box-shadow: 0 0 0 0 transparent;
  }
}

@keyframes glowTrailRight {
  0% {
    opacity: 0;
    box-shadow: 100px 0 60px 20px rgba(18, 121, 164, 0.8);
  }
  30% {
    opacity: 1;
    box-shadow: 50px 0 40px 15px rgba(18, 121, 164, 0.6);
  }
  60% {
    opacity: 0.5;
    box-shadow: 0 0 20px 5px rgba(18, 121, 164, 0.3);
  }
  100% {
    opacity: 0;
    box-shadow: 0 0 0 0 transparent;
  }
}

/* 奖杯图标动画 */
.competition-item.animate-in .competition-icon {
  animation: trophyBounce 0.8s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  animation-delay: 0.6s;
}

@keyframes trophyBounce {
  0% {
    transform: scale(1) rotate(0deg);
  }
  25% {
    transform: scale(1.3) rotate(-10deg);
  }
  50% {
    transform: scale(1.2) rotate(10deg);
  }
  75% {
    transform: scale(1.1) rotate(-5deg);
  }
  100% {
    transform: scale(1) rotate(0deg);
  }
}

/* 文字逐渐清晰效果 */
.competition-item.animate-in .competition-text {
  animation: textReveal 0.8s ease-out forwards;
  animation-delay: 0.4s;
}

@keyframes textReveal {
  0% {
    text-shadow: 0 0 20px rgba(255, 255, 255, 0.8);
  }
  50% {
    text-shadow: 
      0 0 30px rgba(18, 121, 164, 1),
      0 0 60px rgba(18, 121, 164, 0.5);
  }
  100% {
    text-shadow: 0 0 8px rgba(18, 121, 164, 0.4);
  }
}

.competition-item:hover {
  background: rgba(18, 121, 164, 0.2);
  border-color: rgba(18, 121, 164, 0.5);
  transform: translateX(0) scale(1.02);
  box-shadow: 
    0 0 20px rgba(18, 121, 164, 0.3),
    0 0 40px rgba(18, 121, 164, 0.15);
}

.competition-item.expanded {
  background: rgba(18, 121, 164, 0.25);
  border-color: rgba(18, 121, 164, 0.6);
  box-shadow: 
    0 0 25px rgba(18, 121, 164, 0.4),
    0 0 50px rgba(18, 121, 164, 0.2);
  animation: expandedPulse 2s ease-in-out infinite;
}

@keyframes expandedPulse {
  0%, 100% {
    box-shadow: 
      0 0 25px rgba(18, 121, 164, 0.4),
      0 0 50px rgba(18, 121, 164, 0.2);
  }
  50% {
    box-shadow: 
      0 0 35px rgba(18, 121, 164, 0.6),
      0 0 70px rgba(18, 121, 164, 0.3);
  }
}

.competition-icon {
  font-size: clamp(20px, 2.5vw, 32px);
  flex-shrink: 0;
  display: inline-block;
}

.competition-text {
  flex: 1;
  color: #ffffff;
  font-size: clamp(12px, 1.4vw, 18px);
  font-weight: 500;
  letter-spacing: clamp(0.5px, 0.1vw, 1px);
  text-shadow: 0 0 8px rgba(18, 121, 164, 0.4);
  line-height: 1.4;
}

.competition-arrow {
